  (* LPS 727298f3: the launch's reserved intervals at the main entry ([AllocRepX.akernel_resx]),
     from the ledger's shape, the mmap base and the mappings' apartness ([ak_reserved], that is
     [AsanPlanSound.co_res]) and [alloc_top = hceil] ([ak_top], [Hceil]). *)
  Lemma akernel_resx_main : akernel_resx model.
  Proof.
    destruct ak_reserved as [kb (Hr & Hmb & Hd & _)].
    apply (@akernel_resx_intro HCEIL model kb Hr Hmb).
    - rewrite ak_top. symmetry. exact Hceil.
    - intros iv Hiv e He. exact (proj1 (Forall_forall _ _) (proj1 (Forall_forall _ _) Hd iv Hiv) e He).
  Qed.
